use super::*;
fn valid_source(source:&str)->Result<bool,String>{if source.len()>10000{return Err("Source is too long.".into());}if source.starts_with("magnet:?"){let u=Url::parse(source).map_err(|_|"Invalid magnet link")?;if !u.query_pairs().any(|(k,v)|k=="xt"&&v.strip_prefix("urn:btih:").is_some_and(|h|(h.len()==40&&h.bytes().all(|b|b.is_ascii_hexdigit()))||(h.len()==32&&h.bytes().all(|b|b.is_ascii_alphanumeric())))){return Err("Use a supported BitTorrent magnet link.".into());}Ok(true)}else{http_url(source)?;Ok(false)}}
fn largest<'a>(files:&'a Value)->Option<&'a Value>{files.as_array()?.iter().filter(|f|{let name=f["name"].as_str().or(f["path"].as_str()).or(f["short_name"].as_str()).unwrap_or("");browse::is_video(name)&&!name.to_lowercase().contains("sample")}).max_by_key(|f|f["size"].as_u64().or(f["bytes"].as_u64()).unwrap_or(0))}
fn best_ad(nodes:&Value,best:&mut Option<(u64,String)>,depth:usize){if depth>16{return;}if let Some(nodes)=nodes.as_array(){for n in nodes{if n["e"].is_array(){best_ad(&n["e"],best,depth+1);}else if let (Some(name),Some(link))=(n["n"].as_str(),n["l"].as_str()){let size=n["s"].as_u64().unwrap_or(0);if browse::is_video(name)&&!name.to_lowercase().contains("sample")&&best.as_ref().is_none_or(|(s,_)|size>*s){*best=Some((size,link.into()));}}}}}
pub async fn resolve(p:&str,c:&Connection,source:&str)->Result<String,String>{let magnet=valid_source(source)?;let url=match p{
    "premiumize"=>{let data=form(p,c,"transfer/directdl",vec![("src".into(),source.into())]).await?;let file=largest(&data["content"]).ok_or("No ready video was returned. Use a cached source or browse your Premiumize files.")?;file["link"].as_str().or(file["stream_link"].as_str()).ok_or("Premiumize returned no playable URL.")?.to_owned()},
    "alldebrid"=>{let link=if !magnet{source.to_owned()}else{let data=form(p,c,"v4/magnet/upload",vec![("magnets[]".into(),source.into())]).await?;let id=value_string(&data["data"]["magnets"][0]["id"]);super::id(&id)?;let mut ready=false;for _ in 0..8{let data=form(p,c,"v4.1/magnet/status",vec![("id".into(),id.clone())]).await?;let rows=&data["data"]["magnets"];let m=if rows.is_array(){&rows[0]}else{rows};let status=m["statusCode"].as_u64().unwrap_or(0);if status==4{ready=true;break;}if status>4{return Err("AllDebrid could not prepare this source. Try another one.".into());}tokio::time::sleep(Duration::from_secs(2)).await;}if !ready{return Err("This torrent is still preparing in AllDebrid. Browse it again later or choose a cached source.".into());}let data=form(p,c,"v4/magnet/files",vec![("id[]".into(),id)]).await?;let mut best=None;if let Some(magnets)=data["data"]["magnets"].as_array(){for m in magnets{best_ad(&m["files"],&mut best,0);}}best.ok_or("AllDebrid returned no video file.")?.1};let data=form(p,c,"v4/link/unlock",vec![("link".into(),link)]).await?;data["data"]["link"].as_str().ok_or("AllDebrid returned no playable URL.")?.into()},
    "torbox"=>{let (create,list,download,id_param)=if magnet{("torrents/createtorrent","torrents/mylist","torrents/requestdl","torrent_id")}else{("webdl/createwebdownload","webdl/mylist","webdl/requestdl","web_id")};let data=if magnet{let response=authorized(p,c,Method::POST,endpoint(p,c,create)?)?.multipart(reqwest::multipart::Form::new().text("magnet",source.to_owned()).text("allow_zip","false")).send().await.map_err(|_|"TorBox could not be reached.")?;if !response.status().is_success(){return Err("TorBox rejected this source.".into());}serde_json::from_slice::<Value>(&bytes(response,1024*1024).await?).map_err(|_|"Invalid TorBox response.")?}else{form(p,c,create,vec![("link".into(),source.into())]).await?};if data["success"]==false{return Err("TorBox rejected this source or account limit was reached.".into());}let id=value_string(&data["data"][id_param]).replace("null","");let id=if id.is_empty(){let web=value_string(&data["data"]["webdownload_id"]);if web.is_empty(){value_string(&data["data"]["id"])}else{web}}else{id};super::id(&id)?;let mut selected=None;for _ in 0..8{let data=get(p,c,list,&[("id",id.clone()),("files","true".into()),("bypass_cache","true".into())]).await?;let t=if data["data"].is_array(){&data["data"][0]}else{&data["data"]};if t["download_finished"]==true{selected=largest(&t["files"]).cloned();if selected.is_some(){break;}}tokio::time::sleep(Duration::from_secs(2)).await;}let selected=selected.ok_or("TorBox is still preparing this source. Browse it later or choose a cached source.")?;let data=get(p,c,download,&[("token",c.token.clone()),(id_param,id),("file_id",value_string(&selected["id"])),("redirect","false".into())]).await?;data["data"].as_str().ok_or("TorBox returned no playable URL.")?.into()},
    _=>return Err("Select TorBox, Premiumize or AllDebrid for this resolver.".into())
};http_url(&url)?;Ok(url)}
